ssize_t irda_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                     size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int error = -EINVAL;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    if (skb->len > size) {
        msg->msg_flags |= MSG_TRUNC;
        copied = size;
    } else {
        copied = skb->len;
    }

    if (memcpy_toiovec(msg->msg_iov, skb->data, copied) != 0) {
        error = -EFAULT;
        goto out;
    }

    sock_recv_timestamp(msg, sk, skb);
    __sock_recv_ts_and_drops(msg, sk, skb);

    atomic_sub(copied, &sk->sk_rmem_alloc);
    sock->sk_data_processed += copied;

    error = copied;

    if (skb_queue_len(&sk->sk_receive_queue) == 0 &&
        test_and_clear_bit(IRTTP_FLOW_STOP, &sk->sk_irttp->irtt_flags)) {
        /* Restart the IrTTP flow */
        irtt_start_flow(sk);
    }

out:
    kfree_skb(skb);
    return error;
}

int irda_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg,
                 size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0, err = 0;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    if (size < skb->len) {
        msg->msg_flags |= MSG_TRUNC;
        copied = size;
    } else {
        copied = skb->len;
    }

    err = memcpy_to_msg(msg, skb->data, copied);
    if (err) {
        kfree_skb(skb);
        return err;
    }

    kfree_skb(skb);

    if ((sk->sk_shutdown & RCV_SHUTDOWN) && skb_queue_empty(&sk->sk_receive_queue)) {
        msg->msg_flags |= MSG_EOF;
    }

    if (sk->sk_irc_state & IRDA_FLOW_STOPPED && !skb_queue_empty(&sk->sk_receive_queue)) {
        sk->sk_irc_state &= ~IRDA_FLOW_STOPPED;
    }

    return copied;
}

int irda_sock_recvmsg(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb) {
        return -EAGAIN;
    }

    copied = skb->len;
    if (size < copied) {
        copied = size;
        msg->msg_flags |= MSG_TRUNC;
    }

    if (memcpy_to_msg(msg, skb->data, copied)) {
        kfree_skb(skb);
        return -EFAULT;
    }

    kfree_skb(skb);

    if ((flags & MSG_WAITALL) == 0 && skb_queue_len(&sk->sk_receive_queue) > 0) {
        irtt_flow_start(sk);
    }

    return copied;
}

ssize_t irda_recvmsg(struct kiocb *iocb, struct socket *sock,
                     struct msghdr *msg, size_t size, int flags)
{
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int len;

    skb = skb_dequeue(&sk->sk_receive_queue);
    if (!skb)
        return -EAGAIN;

    len = skb->len;
    if (len > size) {
        msg->msg_flags |= MSG_TRUNC;
        len = size;
    }

    if (skb_copy_datagram_to_iter(skb, 0, &msg->msg_iter, len))
        len = -EFAULT;

    kfree_skb(skb);

    if (test_and_clear_bit(IRDA_SKB_STOP_FLOW, &sk->sk_flags))
        irda_start_rx_flow(sk);

    return len;
}

